int main() {
  int N = 1e8;
  std::vector&lt;double&gt; x(N);
  for (int i = 0; i &lt; N; i++)
    x[i] = i / double(N);

  Timer blas, my;
  my.reset();
  double s = 0.0;
  for (int i = 0; i &lt; N; i++)
    s += x[i] * x[i];
  std::cout &lt;&lt; "MY: \t" &lt;&lt; s &lt;&lt; " " &lt;&lt; my.elapsed() &lt;&lt; " s" &lt;&lt; std::endl;

  blas.reset();
  s = cblas_ddot(N, &x[0], 1, &x[0], 1);
  std::cout &lt;&lt; "BLAS: \t" &lt;&lt; s &lt;&lt; " " &lt;&lt; blas.elapsed() &lt;&lt; " s" &lt;&lt; std::endl;

  return 0;
}

