void wrap_double_ptr(double* data, int m, int n) {
  // Default: column-major
  Map&lt;MatrixXd&gt; A_col(data, m, n);
  // Row-major view if your data is row-major
  Map&lt;Eigen::Matrix&lt;double, Eigen::Dynamic, Eigen::Dynamic, RowMajor&gt;&gt; A_row(data, m, n);
}
